export const SUBJECT_PALETTE=['#2563eb','#c2410c','#0f766e','#7c3aed','#be185d','#4d7c0f','#b45309','#0369a1','#a21caf','#15803d','#b91c1c','#4338ca'];
export const validColor=color=>typeof color==='string'&&/^#[0-9a-f]{6}$/i.test(color);
function generated(index){const hue=(index*137.508)%360,s=.68,l=.4,c=(1-Math.abs(2*l-1))*s,x=c*(1-Math.abs((hue/60)%2-1)),m=l-c/2;let rgb=hue<60?[c,x,0]:hue<120?[x,c,0]:hue<180?[0,c,x]:hue<240?[0,x,c]:hue<300?[x,0,c]:[c,0,x];return '#'+rgb.map(v=>Math.round((v+m)*255).toString(16).padStart(2,'0')).join('')}
export function nextSubjectColor(courses){const used=new Set(courses.map(c=>c.color?.toLowerCase()).filter(Boolean));let index=0,color;do{color=SUBJECT_PALETTE[index]||generated(index);index++}while(used.has(color.toLowerCase()));return color}
export function ensureSubjectColors(courses){const assigned=[];for(const course of courses){if(!validColor(course.color)||assigned.some(c=>c.color.toLowerCase()===course.color.toLowerCase()))course.color=nextSubjectColor(assigned);assigned.push(course)}return courses}
export function colorVariables(color){const safe=validColor(color)?color:'#64748b',rgb=safe.slice(1).match(/../g).map(v=>parseInt(v,16)),luminance=rgb.map(v=>{v/=255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4}).reduce((n,v,i)=>n+v*[.2126,.7152,.0722][i],0);const ink=luminance>.18?'#'+rgb.map(v=>Math.round(v*.4).toString(16).padStart(2,'0')).join(''):safe;const dark='#'+rgb.map(v=>Math.round(v+(255-v)*.65).toString(16).padStart(2,'0')).join('');return '--subject-color:'+safe+';--subject-ink:'+ink+';--subject-ink-dark:'+dark}
